def decode(encoded: str, original: str, message: str) -> str:
    """Decodes an encrypted message using a substitution cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic sanity checks
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        # Ensure both characters are single uppercase letters
        if not (e_char.isalpha() and o_char.isalpha() and len(e_char) == 1 and len(o_char) == 1):
            return "Failed"
        # If this encoded character already has a mapping, verify consistency
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

    # All 26 letters must be represented
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

def string_transformation(A: str, B: str, rules: list):
    """
    Perform Breadth-First Search to transform string A into string B using given rules.

    Parameters:
        A (str): Initial string.
        B (str): Target string.
        rules (list): List of (source, target) tuples for transformations.

    Returns:
        int: Minimum number of steps to transform A into B (≤10) if possible.
        str: "NO ANSWER!" if transformation within 10 steps is not possible.
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        return "NO ANSWER!"
    # Quick answer if already equal
    if A == B:
        return 0

    max_steps = 10
    queue = [(A, 0)]
    visited = set([A])

    try:
        while queue:
            current, steps = queue.pop(0)
            if steps >= max_steps:
                continue
            for src, tgt in rules:
                if not isinstance(src, str) or not isinstance(tgt, str):
                    continue
                start = 0
                while True:
                    idx = current.find(src, start)
                    if idx == -1:
                        break
                    new_string = current[:idx] + tgt + current[idx + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                    start = idx + 1
    except Exception:
        return "NO ANSWER!"

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) explores all possible transformations. The function returns the count of
    unique numbers that can be generated from the original number, including the number
    itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is
                                represented as a tuple (x, y) indicating that digit x
                                can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.

    Raises:
        TypeError: If inputs are not of expected type.
        ValueError: If rules are invalid.
    """

    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")

    # Build mapping from source digit to list of target digits (as strings)
    mapping = {}
    for rule in rules:
        if (
            not isinstance(rule, tuple)
            or len(rule) != 2
            or not all(isinstance(x, int) for x in rule)
        ):
            raise ValueError("Each rule must be a tuple of two integers")
        x, y = rule
        if not (0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError("Rule digits must be between 0 and 9")
        x_char, y_char = str(x), str(y)
        mapping.setdefault(x_char, []).append(y_char)

    start = str(n)
    visited = {start}
    queue = [start]

    while queue:
        cur = queue.pop(0)
        for idx, digit in enumerate(cur):
            if digit in mapping:
                for target in mapping[digit]:
                    new_num = cur[:idx] + target + cur[idx + 1 :]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of a modulo b.
    Returns the integer x such that (a * x) % b == 1 if it exists; otherwise None.
    """
    try:
        if b == 0:
            return None
        mod = abs(b)
        a = a % mod

        def egcd(x, y):
            if y == 0:
                return (x, 1, 0)
            g, u, v = egcd(y, x % y)
            return (g, v, u - (x // y) * v)

        g, x, _ = egcd(a, mod)
        if g != 1:
            return None
        return x % mod
    except Exception:
        return None

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    try:
        if heights is None:
            return 0
        if not isinstance(heights, list):
            raise TypeError("heights must be a list of integers")
        n = len(heights)
        if n == 0:
            return 0
        for h in heights:
            if not isinstance(h, int):
                raise TypeError("heights list must contain integers only")

        # Longest increasing subsequence ending at each index
        lis = [1] * n
        for i in range(n):
            for j in range(i):
                if heights[j] < heights[i]:
                    lis[i] = max(lis[i], lis[j] + 1)

        # Longest decreasing subsequence starting at each index
        lds = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                if heights[i] > heights[j]:
                    lds[i] = max(lds[i], lds[j] + 1)

        # Maximum bitonic subsequence length
        max_lbs = 0
        for i in range(n):
            max_lbs = max(max_lbs, lis[i] + lds[i] - 1)

        return n - max_lbs
    except Exception as e:
        # In case of unexpected errors, raise a ValueError with a descriptive message
        raise ValueError(f"An error occurred while computing the minimum students to leave: {e}") from e

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")
    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError(f"Each item must be a tuple of length 3, error at index {idx}")
        student_number, total_score, chinese_score = item
        if not all(isinstance(x, int) for x in (student_number, total_score, chinese_score)):
            raise ValueError(f"All tuple elements must be integers, error at index {idx}")
    try:
        return sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])
        )
    except Exception as e:
        raise RuntimeError(f"Error during sorting: {e}") from e
